        </div>

        <div class="filter-bar" id="filter-bar" style="display: none;">
            <div class="filter-item">
                <select id="bolt-filter" onchange="szuroAkcio()">
                    <option value="">Minden bolt</option>
                    <option value="JYSK">JYSK</option>
