                <input type="number" id="min-discount" placeholder="Min kedvezmény %" onchange="szuroAkcio()">
            </div>
            <div class="filter-item">
                <input type="text" id="search-term" placeholder="Keresés termékben..." onchange="szuroAkcio()">
            </div>
        </div>
    </div>

    <div class="container">
        <div id="loading" class="loading">
            <div class="spinner"></div>
            Akciók betöltése...
        </div>

        <div id="content" style="display: none;">
            <div id="akcio-lista" class="akcio-grid">
                <!-- Akciók dinamikusan töltődnek ide -->
            </div>
        </div>

        <div id="empty-state" class="empty-state" style="display: none;">
            <h2>🤔 Nincsenek akciók</h2>
            <p>Próbálja meg frissíteni az oldalt vagy változtassa meg a szűrőket!</p>
        </div>
    </div>

    <script>
        let osszesAkcio = [];
        let szurtAkcio = [];

        async function betoltAkcio() {
            try {
                document.getElementById('loading').style.display = 'block';
                document.getElementById('content').style.display = 'none';
                document.getElementById('empty-state').style.display = 'none';

                const response = await fetch('/api/akciok');
                const data = await response.json();

                osszesAkcio = data.akciok || [];
                szurtAkcio = [...osszesAkcio];

                document.getElementById('total-count').textContent = osszesAkcio.length;
                document.getElementById('last-update').textContent = data.utolso_frissites || 'Ismeretlen';

                megjelenit Akcio();

            } catch (error) {
                console.error('Hiba az akciók betöltése során:', error);
                document.getElementById('empty-state').style.display = 'block';
            } finally {
                document.getElementById('loading').style.display = 'none';
            }
        }

        function megjelenitAkcio() {
            const container = document.getElementById('akcio-lista');

            if (szurtAkcio.length === 0) {
                document.getElementById('content').style.display = 'none';
                document.getElementById('empty-state').style.display = 'block';
                return;
            }

            document.getElementById('content').style.display = 'block';
            document.getElementById('empty-state').style.display = 'none';

            container.innerHTML = szurtAkcio.map(akcio => `
                <div class="akcio-card">
                    <div class="bolt-badge">${akcio.bolt}</div>
                    <div class="kedvezmeny-badge">-${akcio.kedvezmeny}%</div>

                    <div class="termek-info">
                        <h3 class="termek-nev">${akcio.termek}</h3>

                        <div class="arak">
