                const searchOk = !searchTerm || akcio.termek.toLowerCase().includes(searchTerm);

                return boltOk && discountOk && searchOk;
            });

            megjelenitAkcio();
        }

        async function frissitAkcio() {
            const btn = document.querySelector('.btn-primary');
            btn.textContent = '⏳ Frissítés...';
            btn.disabled = true;

            try {
                await fetch('/api/frissites');
